//! Drift guard: the committed proof bundle must be the bundle of *this*
//! `clean/veripb_kernel.lean`.
//!
//! `downstream proof consumer cert verify` replays every stored proof term against its own
//! stored statement. That establishes nothing about *which* statements those
//! are, and nothing at all about whether the bundle was exported from the
//! `.lean` that is committed next to it: a stale bundle from an older kernel
//! replays `N passed, 0 failed` just as happily.
//!
//! `veripb_kernel.manifest.txt` closes that hole. It is regenerated by
//! `scripts/verify-proofs.sh --refresh` from `downstream proof consumer cert inspect`, and
//! records, per theorem, the name, the `type_hash` (the STATEMENT) and the
//! `proof_hash` (the proof term). This test compares the theorem names in the
//! manifest against the theorem names in the `.lean`, under stock `cargo test`,
//! in milliseconds and with no toolchain present -- so a forgotten `--refresh`
//! fails in ordinary CI rather than only on the one machine that has `clean`.
//!
//! What this test canNOT see (by construction, since it has no `clean`):
//! whether a manifest hash is the hash of the theorem it is filed under. That
//! is what the `bundle identity` stage of `scripts/verify-proofs.sh` checks,
//! by re-deriving the manifest from the bundle and diffing.

use std::collections::BTreeSet;
use std::path::PathBuf;

fn crate_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

/// Strip Lean block/line comments so that a `theorem` word inside prose is not
/// mistaken for a declaration. Same walker as `island_sync.rs`, kept
/// deliberately simple; it does not need the ASCII rewriting that one does.
fn strip_comments(src: &str) -> String {
    let chars: Vec<char> = src.chars().collect();
    let mut out = String::new();
    let mut i = 0usize;
    let mut depth = 0usize;
    while i < chars.len() {
        let two: String = chars[i..(i + 2).min(chars.len())].iter().collect();
        if two == "/-" {
            depth += 1;
            i += 2;
            continue;
        }
        if two == "-/" && depth > 0 {
            depth -= 1;
            i += 2;
            continue;
        }
        if depth > 0 {
            i += 1;
            continue;
        }
        if two == "--" {
            while i < chars.len() && chars[i] != '\n' {
                i += 1;
            }
            continue;
        }
        out.push(chars[i]);
        i += 1;
    }
    out
}

/// Theorem names declared in the `.lean`, qualified the way the bundle
/// qualifies them: inside `namespace VeriPbCore` they get the prefix, and the
/// citation-discharging addendum after `end VeriPbCore` does not.
fn lean_theorem_names(lean: &str) -> BTreeSet<String> {
    let mut names = BTreeSet::new();
    let mut in_ns = false;
    for line in strip_comments(lean).lines() {
        let t = line.trim_end();
        if let Some(rest) = t.strip_prefix("namespace ") {
            if rest.trim() == "VeriPbCore" {
                in_ns = true;
            }
            continue;
        }
        if let Some(rest) = t.strip_prefix("end ") {
            if rest.trim() == "VeriPbCore" {
                in_ns = false;
            }
            continue;
        }
        let Some(rest) = t.strip_prefix("theorem ") else {
            continue;
        };
        let name: String = rest
            .chars()
            .take_while(|c| c.is_alphanumeric() || *c == '_' || *c == '\'' || *c == '.')
            .collect();
        if name.is_empty() {
            continue;
        }
        names.insert(if in_ns {
            format!("VeriPbCore.{name}")
        } else {
            name
        });
    }
    names
}

/// Marker in the `.lean` splitting the certificate-exportable prefix from the
/// trailing declarations `clean export-cert` cannot handle. See the comment at
/// the marker itself, and `veripb-core-proved/clean/README.md`.
const EXPORT_BOUNDARY: &str = "-- EXPORT-CERT-BOUNDARY";

/// `(exportable prefix, excluded remainder)`.
fn split_at_export_boundary(lean: &str) -> (&str, &str) {
    match lean.find(EXPORT_BOUNDARY) {
        Some(i) => (&lean[..i], &lean[i..]),
        None => (lean, ""),
    }
}

fn manifest_theorem_names(manifest: &str) -> BTreeSet<String> {
    manifest
        .lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
        .map(|l| l.split_whitespace().next().unwrap_or_default().to_string())
        .collect()
}

const REFRESH: &str =
    "re-export the bundle and re-bless the manifest: scripts/verify-proofs.sh --refresh";

#[test]
fn the_bundle_manifest_covers_exactly_the_checked_lean_theorems() {
    let lean = std::fs::read_to_string(crate_dir().join("clean/veripb_kernel.lean"))
        .expect("clean/veripb_kernel.lean must exist");
    let manifest_path = crate_dir().join("clean/veripb_kernel.manifest.txt");
    let manifest = std::fs::read_to_string(&manifest_path).unwrap_or_else(|e| {
        panic!(
            "{}: no committed bundle manifest ({e}).\n\
             Without it, `downstream proof consumer cert verify` gates only on \
             'nothing failed', which a bundle of one theorem also satisfies.\n{REFRESH}",
            manifest_path.display()
        )
    });

    let (exportable, excluded) = split_at_export_boundary(&lean);
    let want = lean_theorem_names(exportable);
    let got = manifest_theorem_names(&manifest);
    assert!(
        !want.is_empty(),
        "extracted zero theorem names from the .lean -- this test would be vacuous"
    );

    let missing: Vec<_> = want.difference(&got).cloned().collect();
    let extra: Vec<_> = got.difference(&want).cloned().collect();
    assert!(
        missing.is_empty() && extra.is_empty(),
        "the committed proof bundle is not the bundle of this \
         clean/veripb_kernel.lean.\n\
         {} theorem(s) in the .lean are absent from the bundle: {:?}\n\
         {} theorem(s) in the bundle are absent from the .lean: {:?}\n{REFRESH}",
        missing.len(),
        &missing[..missing.len().min(12)],
        extra.len(),
        &extra[..extra.len().min(12)],
    );

    // The excluded tail is not in the bundle by design, so nothing above would
    // notice it disappearing. Pin it here instead: it must still be present,
    // and none of its theorems may leak into the manifest under the pretence
    // of having been replayed.
    if !excluded.is_empty() {
        let excluded_names = lean_theorem_names(excluded);
        assert!(
            !excluded_names.is_empty(),
            "the .lean carries an EXPORT-CERT-BOUNDARY marker but declares no \
             theorem after it; drop the marker rather than leaving a boundary \
             that excludes nothing"
        );
        let leaked: Vec<_> = excluded_names.intersection(&got).cloned().collect();
        assert!(
            leaked.is_empty(),
            "the manifest claims replayed proofs for {leaked:?}, which are \
             below the EXPORT-CERT-BOUNDARY and therefore were never exported"
        );
    }
}

/// The prose about the export boundary must name every theorem the boundary
/// excludes.
///
/// This is the check that was missing when the documentation said "those four
/// are the ones a third party cannot replay" about a set of six: the two
/// rule-guard theorems `weaken_factor_sign_exact` and `guard_fits_lower_exact`
/// went unmentioned, and they are the load-bearing pair -- the only two
/// citations whose *deletion* compiler_consumer notices on its own. A count in prose can
/// drift silently; a name cannot, because adding a seventh excluded theorem
/// fails here until someone writes it down.
///
/// the development design notes is where the claim is made and is therefore required
/// to carry every name. The other two files are accepted as alternative homes
/// so that a future reorganisation does not have to fight this test.
#[test]
fn the_docs_name_every_theorem_the_export_boundary_excludes() {
    let lean = std::fs::read_to_string(crate_dir().join("clean/veripb_kernel.lean"))
        .expect("clean/veripb_kernel.lean must exist");
    let (_, excluded) = split_at_export_boundary(&lean);
    let names = lean_theorem_names(excluded);
    assert!(
        !names.is_empty(),
        "no theorems below the EXPORT-CERT-BOUNDARY marker; this test would be vacuous"
    );

    let repo_root = crate_dir()
        .parent()
        .expect("veripb-core-proved has a parent")
        .to_path_buf();
    let docs: Vec<(&str, String)> = [
        "the development design notes",
        "README.md",
        "veripb-core-proved/clean/README.md",
    ]
    .iter()
    .map(|rel| {
        let path = repo_root.join(rel);
        let text = std::fs::read_to_string(&path)
            .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
        (*rel, text)
    })
    .collect();

    let unnamed: Vec<&String> = names
        .iter()
        .filter(|name| {
            // The `.lean` declares these outside `namespace VeriPbCore`, so
            // `lean_theorem_names` returns them bare; prose spells them the
            // same way.
            !docs.iter().any(|(_, text)| text.contains(name.as_str()))
        })
        .collect();
    assert!(
        unnamed.is_empty(),
        "the `-- EXPORT-CERT-BOUNDARY` marker excludes {} theorem(s) from the \
         proof bundle, and {} of them are named in none of {:?}: {unnamed:?}.\n\
         Excluding a theorem from the bundle is a limit on what a third party \
         can replay, so it has to be written down where the replay claim is \
         made -- see the development design notes \u{a7}4.1.",
        names.len(),
        unnamed.len(),
        docs.iter().map(|(rel, _)| *rel).collect::<Vec<_>>(),
    );
}

#[test]
fn the_manifest_header_states_the_kernel_it_was_exported_from() {
    let manifest_path = crate_dir().join("clean/veripb_kernel.manifest.txt");
    let Ok(manifest) = std::fs::read_to_string(&manifest_path) else {
        panic!("{}: missing.\n{REFRESH}", manifest_path.display());
    };
    // `island_sha256` is the sha256 of the comment-stripped, ASCII kernel text
    // -- i.e. of the Clean island itself. `scripts/verify-proofs.sh` recomputes
    // it and rejects a bundle whose header disagrees; assert here only that the
    // header exists and is well-formed, since hashing needs no toolchain but a
    // sha256 implementation is not worth a dependency in this crate.
    let sha = manifest
        .lines()
        .find_map(|l| l.strip_prefix("# island_sha256 "))
        .unwrap_or_else(|| {
            panic!("the manifest has no `# island_sha256` header, so nothing ties the bundle to a specific kernel source.\n{REFRESH}")
        })
        .trim();
    assert!(
        sha.len() == 64 && sha.chars().all(|c| c.is_ascii_hexdigit()),
        "malformed island_sha256 header {sha:?}\n{REFRESH}"
    );

    let claimed: usize = manifest
        .lines()
        .find_map(|l| l.strip_prefix("# theorems "))
        .and_then(|n| n.trim().parse().ok())
        .unwrap_or_else(|| panic!("the manifest has no `# theorems N` header.\n{REFRESH}"));
    let actual = manifest_theorem_names(&manifest).len();
    assert_eq!(
        claimed, actual,
        "the manifest header claims {claimed} theorems but lists {actual}"
    );
}

#[test]
fn the_pins_file_states_a_magnitude_for_every_gate() {
    // The counts `scripts/verify-proofs.sh` gates on. Checked here so that a
    // pins file emptied or truncated by hand fails under stock `cargo test`
    // rather than only when someone happens to have both toolchains.
    let path = crate_dir().join("clean/proved-core-expected.txt");
    let pins = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}\n{REFRESH}", path.display()));
    for key in [
        "kernel_decls",
        "kernel_island_sha256",
        "bundle_theorems",
        "island_decls",
        "island_citations",
        "island_cited_names",
        "island_proved_obligations",
        "wholecrate_proved_floor",
        "wholecrate_incomplete_ceiling",
        "clean_toolchain",
        "trustc_toolchain",
    ] {
        let value = pins
            .lines()
            .find_map(|l| l.strip_prefix(&format!("{key}=")))
            .unwrap_or_else(|| panic!("{key} is not pinned in {}\n{REFRESH}", path.display()));
        assert!(
            !value.trim().is_empty(),
            "{key} is pinned to an empty value in {}; a gate reading it would \
             be vacuous\n{REFRESH}",
            path.display()
        );
    }
    // A zero count is the vacuous case the whole pins file exists to exclude.
    // The whole-crate ratchet is the one exception: when it is pinned as
    // unavailable its floors are meaningless, and the script asserts the
    // unavailability diagnostic instead of the numbers.
    let mut keys = vec![
        "kernel_decls",
        "bundle_theorems",
        "island_decls",
        "island_citations",
        "island_proved_obligations",
    ];
    if pins
        .lines()
        .any(|l| l.trim() == "wholecrate_ratchet=enabled")
    {
        keys.push("wholecrate_proved_floor");
    }
    for key in keys {
        let value: u64 = pins
            .lines()
            .find_map(|l| l.strip_prefix(&format!("{key}=")))
            .and_then(|v| v.trim().parse().ok())
            .unwrap_or_else(|| panic!("{key} is not a number in {}", path.display()));
        assert!(value > 0, "{key} is pinned to 0, so its gate cannot bite");
    }
}

/// The committed proof bundle must have been exported from the committed kernel.
///
/// See the comment inside: this is what makes every `type_hash` in the
/// manifest -- `checker_sound`'s included -- a pin on a statement that is
/// actually in this tree.
#[test]
fn the_bundle_was_exported_from_the_committed_kernel() {
    let pins = std::fs::read_to_string(crate_dir().join("clean/proved-core-expected.txt"))
        .expect("pins file must exist");
    // The bundle must describe the kernel that is actually committed.
    //
    // Every theorem's STATEMENT is pinned by its `type_hash` in the manifest
    // -- including `checker_sound`, the top-level soundness theorem, whose
    // hypotheses could otherwise be weakened with nothing to notice. But the
    // manifest is derived from the BUNDLE, so those hashes describe whatever
    // kernel was last exported, which need not be the one in the tree. The
    // `# island_sha256` header is the only thing tying the two together, and
    // until now nothing without a toolchain compared it to anything: the
    // header was checked for well-formedness alone.
    //
    // `kernel_island_sha256` is that same digest, measured from the .lean by
    // `scripts/regen-island.py --sha256` and committed beside it. Requiring
    // the two to agree makes "the kernel moved but the bundle did not" a
    // stock `cargo test` failure instead of something only the full
    // toolchain run discovers -- which is how it was found: an edit to the
    // kernel left this header ten minutes' verification behind.
    let manifest = std::fs::read_to_string(crate_dir().join("clean/veripb_kernel.manifest.txt"))
        .expect("clean/veripb_kernel.manifest.txt must exist");
    let header_sha = manifest
        .lines()
        .find_map(|l| l.strip_prefix("# island_sha256 "))
        .expect("manifest has no island_sha256 header")
        .trim();
    let pinned_sha = pins
        .lines()
        .find_map(|l| l.strip_prefix("kernel_island_sha256="))
        .expect("kernel_island_sha256 is not pinned")
        .trim();
    assert_eq!(
        header_sha, pinned_sha,
        "the proof bundle and the pinned kernel hash disagree: \
         veripb_kernel.manifest.txt says the bundle was exported from \
         {header_sha}, but proved-core-expected.txt pins the kernel at \
         {pinned_sha}. If the manifest is the stale one, every type_hash in it \
         -- including checker_sound's -- pins the statements of a kernel that \
         is no longer in this tree.\n\n\
         Both values are read from COMMITTED FILES; neither is measured from \
         clean/veripb_kernel.lean here. To find out which one moved, compare \
         both against `python3 scripts/regen-island.py --sha256`: whichever \
         differs from it is the one left behind.\n\
         {REFRESH}"
    );
}
